 // Cria uma lista vazia para guardar os CNPJs limpos

const resultados = [];


// Pega a lista "organic" que veio do nó do Serper

const organic = $input.first().json.organic || [];


// O código Regex mágico que reconhece o padrão de um CNPJ 

const regexCnpj = /\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2}|\b\d{14}\b/g;


// Faz uma varredura em cada um dos resultados do Google

for (const item of organic) {

  if (item.snippet) {

    // Procura o CNPJ dentro do texto do snippet

    const cnpjsEncontrados = item.snippet.match(regexCnpj);



    if (cnpjsEncontrados) {

      for (let cnpj of cnpjsEncontrados) {

        // Limpa a sujeira: remove pontos, barra e traço

        const cnpjLimpo = cnpj.replace(/[^\d]/g, '');



        // Salva o CNPJ limpo, junto com o nome da empresa e o link do Econodata

        resultados.push({

          json: {

            cnpj: cnpjLimpo

          }

        });

      }

    }

  }

}


// Devolve a lista perfeita para o n8n

return resultados;

