const raiz = $input.first().json.estabelecimento.cnpj_raiz.toString().padStart(8, '0');
const ordem = $input.first().json.estabelecimento.cnpj_ordem.toString().padStart(4, '0');
const dv = $input.first().json.estabelecimento.cnpj_digito_verificador.toString().padStart(2, '0');
