const razao_social = $input.first().json.razao_social;
const nome_fantasia = $input.first().json.estabelecimento.nome_fantasia;
let nome;
if (razao_social == null || nome_fantasia == null){
  nome = nome_fantasia || razao_social;
}
else{
  nome = razao_social + '/' + nome_fantasia;
}
return {
  "nome" : nome,
  "setor" :$input.first().json.estabelecimento.atividade_principal.descricao,
  "local" : $input.first().json.estabelecimento.cidade.nome + ' - ' + $input.first().json.estabelecimento.estado.sigla,
  "cnpj" : cnpjFormatado,
