// 2. O nome da tabela que você quer ver (mude para o nome real dela)
const tableName = 'leads'; 

try {
  // O comando '-header' mostra os nomes das colunas e '-json' formata como JSON
  const resultado = execSync(`sqlite3 -header -json ${dbPath} "SELECT * FROM ${tableName};"`).toString();

  // Se a tabela estiver vazia, o resultado será uma string vazia
  if (!resultado) {
    return { mensagem: "A tabela está vazia." };
  }

  // Transformamos a string de texto em um objeto JSON real para o n8n mostrar bonitinho
  const dadosFinais = JSON.parse(resultado);

  return dadosFinais;

} catch (error) {
  return { erro: "Não foi possível ler a tabela. Verifique se o nome está correto.", detalhes: error.message };
}

