const Database = require('better-sqlite3');
const db = new Database('/home/itajradmin/n8n/prospecta.db');

const setor = $input.first().json.setor;
const local = $input.first().json.local;

const rows = db.prepare(`
  SELECT Nome, Setor, Local, Telefone, Email 
  FROM empresa 
  WHERE Setor = ? AND Local = ?
`).all(setor, local);

let html = '<table><tr><th>Nome</th><th>Setor</th><th>Local</th><th>Telefone</th><th>Email</th></tr>';

for (const r of rows) {
  html += `<tr>
    <td>${r.Nome}</td>
    <td>${r.Setor}</td>
    <td>${r.Local}</td>
    <td>${r.Telefone}</td>
    <td>${r.Email}</td>
  </tr>`;
}

html += '</table>';

return [{ json: { html } }];

